package com.garagedesk.service; import com.garagedesk.entity.Vehicle; import com.garagedesk.exception.*; import com.garagedesk.repo.VehicleRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class VehicleService{final VehicleRepository r; public VehicleService(VehicleRepository r){this.r=r;} public List<Vehicle> all(){return r.findAll();} public Vehicle get(Long id){return r.findById(id).orElseThrow(()->new ResourceNotFoundException("Vehicle not found: "+id));} public Vehicle create(Vehicle v){r.findByRegistrationNumberIgnoreCase(v.getRegistrationNumber()).ifPresent(x->{throw new ConflictException("Registration number already exists");});return r.save(v);} public Vehicle update(Long id,Vehicle x){Vehicle v=get(id);r.findByRegistrationNumberIgnoreCase(x.getRegistrationNumber()).filter(y->!y.getId().equals(id)).ifPresent(y->{throw new ConflictException("Registration number already exists");});v.setRegistrationNumber(x.getRegistrationNumber());v.setModel(x.getModel());v.setOwnerName(x.getOwnerName());v.setOwnerPhone(x.getOwnerPhone());return r.save(v);} public void delete(Long id){r.delete(get(id));}}
